// Ambient domain type declarations for ag-doctor-ui renderer.
// Loaded ambiently across the renderer TypeScript project.

interface CheckResult {
  id: string;
  title: string;
  status: 'ok' | 'warn' | 'error' | 'info';
  message: string;
  details?: string;
  fixable?: boolean;
  data?: unknown;
}

interface CustomModel {
  name: string;
  displayName?: string;
  description?: string;
  provider: string;
  apiKey?: string;
  apiUrl: string;
  externalModelName: string;
  encrypted?: boolean;
  enabled?: boolean;
  accountName?: string;
  accountEmail?: string;
  providerId?: string;
}

interface ModelsFile {
  path: string;
  encrypted: boolean;
  models: CustomModel[];
}

interface PatchStatus {
  antigravityVersion: string | null;
  antigravityVersionSource?: string;
  binaryPath: string | null;
  exists: boolean;
  applied: boolean;
  backupExists: boolean;
  compatible: boolean;
  warningMessage?: string | null;
  binarySignatureDetected?: boolean;
  binarySignatureState?: 'original' | 'patched' | 'none';
  overlayFingerprintDetected?: boolean;
  overlayFingerprintRange?: string | null;
  overlayFingerprintConfidence?: 'high' | 'medium' | 'low';
  overlayFingerprintReason?: string | null;
  detectionConfidence?: 'high' | 'medium' | 'low';
  detectionReason?: string | null;
  deltaSizeBytes?: number | null;
  recommendedPatch: {
    versionRange: string;
    description: string;
    originalUrl: string;
    patchedUrl: string;
  } | null;
  detectedPatches: Array<{
    versionRange: string;
    description: string;
    originalUrl: string;
    patchedUrl: string;
  }>;
  overrideActive?: boolean;
  recommendedSource?: 'auto' | 'override' | 'none';
  overrideInfo?: {
    range: string;
    reason: string | null;
    setAt: string | null;
  } | null;
  availableRanges?: Array<{
    versionRange: string;
    description: string;
    originalUrl: string;
    patchedUrl: string;
  }>;
}

interface MitmStatus {
  ca: {
    generated: boolean;
    path: string | null;
    fingerprint: string | null;
    installed: boolean;
    expiresAt?: string | null;
    isExpired?: boolean;
  };
  proxy: {
    host: string | null;
    port: number | null;
    redirected: boolean;
  };
  interception: {
    listening: boolean;
    reachable: boolean;
    bypassed: boolean;
  };
}
